import json
import os
from pathlib import Path
from typing import Optional, Union

import torch
import torch.nn as nn
import torch.nn.functional as F
from transformers import AutoModelForCausalLM

MODEL_ID = "Qwen/Qwen3-4B"
ARTIFACT_DIR = Path(__file__).resolve().parent / "quantized_qwen3_4b"
SIZE_METADATA_PATH = ARTIFACT_DIR / "size_metadata.json"
BnbModel = Optional[nn.Module]


class Int8Linear(nn.Module):
    """Simple per-output-channel int8 linear layer.

    This is used only as a fallback when bitsandbytes is unavailable.
    """

    def __init__(self, in_features: int, out_features: int, has_bias: bool):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.register_buffer("qweight", torch.zeros(out_features, in_features, dtype=torch.int8))
        self.register_buffer("scale", torch.ones(out_features, dtype=torch.float16))
        if has_bias:
            self.register_buffer("bias", torch.zeros(out_features, dtype=torch.float16))
        else:
            self.bias = None

    @classmethod
    def from_linear(cls, linear: nn.Linear) -> "Int8Linear":
        out_features, in_features = linear.weight.shape
        layer = cls(in_features=in_features, out_features=out_features, has_bias=linear.bias is not None)
        with torch.no_grad():
            w = linear.weight.detach().to(torch.float32)
            max_abs = w.abs().amax(dim=1)
            scale = torch.clamp(max_abs / 127.0, min=1e-8)
            q = torch.clamp(torch.round(w / scale.unsqueeze(1)), -127, 127).to(torch.int8)
            layer.qweight.copy_(q)
            layer.scale.copy_(scale.to(torch.float16))
            if linear.bias is not None:
                layer.bias.copy_(linear.bias.detach().to(torch.float16))
        return layer

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.qweight.to(torch.float32) * self.scale.unsqueeze(1).to(torch.float32)
        bias = self.bias.to(torch.float32) if self.bias is not None else None
        out = F.linear(x.to(torch.float32), w, bias)
        return out.to(x.dtype)


def _to_device_map(device: Union[str, torch.device]):
    if isinstance(device, torch.device):
        device_str = str(device)
    else:
        device_str = str(device)

    if device_str.startswith("cuda"):
        return {"": device_str}
    return {"": "cpu"}


def _to_torch_device(device: Union[str, torch.device]) -> torch.device:
    if isinstance(device, torch.device):
        return device
    return torch.device(str(device))


def _from_pretrained_with_optional_device_map(model_id_or_path, *, use_bnb_cfg, device):
    kwargs = {"low_cpu_mem_usage": True}
    if use_bnb_cfg is not None:
        kwargs["quantization_config"] = use_bnb_cfg
    kwargs["device_map"] = _to_device_map(device)
    if isinstance(model_id_or_path, Path):
        kwargs["local_files_only"] = True

    try:
        return AutoModelForCausalLM.from_pretrained(model_id_or_path, **kwargs)
    except ValueError as exc:
        if "requires `accelerate`" not in str(exc):
            raise

    kwargs.pop("device_map", None)
    model = AutoModelForCausalLM.from_pretrained(model_id_or_path, **kwargs)
    model.to(_to_torch_device(device))
    return model


def _dir_size_bytes(path: Path) -> int:
    total = 0
    for root, _, files in os.walk(path):
        for name in files:
            total += (Path(root) / name).stat().st_size
    return total


def _swap_linears_to_int8(module: nn.Module):
    for name, child in list(module.named_children()):
        if isinstance(child, nn.Linear):
            setattr(module, name, Int8Linear.from_linear(child))
        else:
            _swap_linears_to_int8(child)


def _load_or_build_bnb(device: Union[str, torch.device]) -> BnbModel:
    try:
        from transformers import BitsAndBytesConfig
    except Exception:
        return None

    ARTIFACT_DIR.mkdir(parents=True, exist_ok=True)
    marker = ARTIFACT_DIR / "bnb_quantized.marker"

    quant_cfg = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_use_double_quant=True,
        bnb_4bit_compute_dtype=torch.float16,
    )

    try:
        if not marker.exists():
            model = _from_pretrained_with_optional_device_map(
                MODEL_ID, use_bnb_cfg=quant_cfg, device=device
            )
            model.eval()
            model.save_pretrained(ARTIFACT_DIR, safe_serialization=True)
            marker.write_text("ok", encoding="utf-8")
            size_bytes = _dir_size_bytes(ARTIFACT_DIR)
            SIZE_METADATA_PATH.write_text(json.dumps({"size_bytes": size_bytes}), encoding="utf-8")
            return model

        model = _from_pretrained_with_optional_device_map(
            ARTIFACT_DIR, use_bnb_cfg=quant_cfg, device=device
        )
        model.eval()
        if not SIZE_METADATA_PATH.exists():
            size_bytes = _dir_size_bytes(ARTIFACT_DIR)
            SIZE_METADATA_PATH.write_text(json.dumps({"size_bytes": size_bytes}), encoding="utf-8")
        return model
    except ImportError:
        return None


def _load_or_build_int8_fallback(device: Union[str, torch.device]) -> nn.Module:
    ARTIFACT_DIR.mkdir(parents=True, exist_ok=True)
    state_path = ARTIFACT_DIR / "fallback_int8_state.pt"
    cfg_path = ARTIFACT_DIR / "config.json"

    model = AutoModelForCausalLM.from_pretrained(MODEL_ID, dtype=torch.float16, low_cpu_mem_usage=True)

    _swap_linears_to_int8(model)

    if state_path.exists():
        state = torch.load(state_path, map_location="cpu")
        model.load_state_dict(state, strict=True)
    else:
        torch.save(model.state_dict(), state_path)
        model.config.save_pretrained(ARTIFACT_DIR)

    if not cfg_path.exists():
        model.config.save_pretrained(ARTIFACT_DIR)

    if isinstance(device, torch.device):
        move_device = device
    else:
        move_device = torch.device(device)
    model.to(move_device)
    model.eval()

    size_bytes = _dir_size_bytes(ARTIFACT_DIR)
    SIZE_METADATA_PATH.write_text(json.dumps({"size_bytes": size_bytes}), encoding="utf-8")
    return model


def load_model(device="cuda"):
    """Load quantized Qwen3-4B model.

    Primary path: bitsandbytes 4-bit NF4 + double quantization.
    Fallback path: per-channel int8 linear quantization.
    """
    model = _load_or_build_bnb(device)
    if model is not None:
        return model
    return _load_or_build_int8_fallback(device)


def get_compressed_size() -> int:
    """Return on-disk compressed size in bytes.

    If metadata is missing, compute size from current artifact directory.
    """
    if SIZE_METADATA_PATH.exists():
        try:
            data = json.loads(SIZE_METADATA_PATH.read_text(encoding="utf-8"))
            size_bytes = int(data["size_bytes"])
            if size_bytes > 0:
                return size_bytes
        except Exception:
            pass

    if ARTIFACT_DIR.exists():
        size_bytes = _dir_size_bytes(ARTIFACT_DIR)
        if size_bytes > 0:
            SIZE_METADATA_PATH.write_text(json.dumps({"size_bytes": size_bytes}), encoding="utf-8")
            return size_bytes

    # Build artifacts on CPU if size is requested before model load.
    _ = load_model(device="cpu")
    size_bytes = _dir_size_bytes(ARTIFACT_DIR)
    SIZE_METADATA_PATH.write_text(json.dumps({"size_bytes": size_bytes}), encoding="utf-8")
    return size_bytes

import gc
import json
import os
from pathlib import Path
from typing import Any

import bitsandbytes.functional as bnbF
import torch
from accelerate import init_empty_weights
from accelerate.utils import set_module_tensor_to_device
from transformers import AutoConfig, AutoModelForCausalLM

MODEL_ID = "Qwen/Qwen3-4B"
ARTIFACT_DIR = Path(__file__).resolve().parent / "qwen3_4b_mixquant"
MANIFEST_PATH = ARTIFACT_DIR / "manifest.json"

INT8_GROUP_SIZE = 128
NF4_BLOCK_SIZE = 32
INT8_TARGETS = (
    ".self_attn.q_proj.weight",
    ".self_attn.k_proj.weight",
    ".self_attn.v_proj.weight",
)


def _artifact_files() -> list[Path]:
    if not MANIFEST_PATH.exists():
        return []
    manifest = json.loads(MANIFEST_PATH.read_text())
    return [ARTIFACT_DIR / rel_path for rel_path in manifest["files"]]


def _artifacts_ready() -> bool:
    if not MANIFEST_PATH.exists():
        return False
    try:
        for path in _artifact_files():
            if not path.exists():
                return False
    except Exception:
        return False
    return True


def _resolve_device(device: str | torch.device) -> torch.device:
    return device if isinstance(device, torch.device) else torch.device(device)


def _tensor_to_cpu(obj: Any) -> Any:
    if torch.is_tensor(obj):
        return obj.detach().cpu().contiguous()
    if isinstance(obj, dict):
        return {k: _tensor_to_cpu(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return type(obj)(_tensor_to_cpu(v) for v in obj)
    return obj


def _quantize_int8(weight: torch.Tensor) -> dict[str, Any]:
    rows, cols = weight.shape
    assert cols % INT8_GROUP_SIZE == 0, (rows, cols)
    groups = cols // INT8_GROUP_SIZE
    view = weight.reshape(rows, groups, INT8_GROUP_SIZE).float()
    scales = view.abs().amax(dim=-1) / 127.0
    scales = torch.where(scales > 0, scales, torch.ones_like(scales))
    qweight = torch.round(view / scales.unsqueeze(-1)).clamp_(-127, 127).to(torch.int8)
    qweight = qweight.reshape(rows, cols).contiguous()
    return {
        "scheme": "int8_sym",
        "shape": list(weight.shape),
        "group_size": INT8_GROUP_SIZE,
        "qweight": qweight.cpu(),
        "scales": scales.to(torch.float16).cpu().contiguous(),
    }


def _dequantize_int8(item: dict[str, Any], device: torch.device) -> torch.Tensor:
    rows, cols = item["shape"]
    group_size = int(item["group_size"])
    groups = cols // group_size
    qweight = item["qweight"].to(device=device, dtype=torch.float32)
    scales = item["scales"].to(device=device, dtype=torch.float32)
    weight = qweight.reshape(rows, groups, group_size) * scales.unsqueeze(-1)
    return weight.reshape(rows, cols).to(torch.float16)


def _quantize_nf4(weight: torch.Tensor) -> dict[str, Any]:
    qweight, quant_state = bnbF.quantize_4bit(
        weight.contiguous(),
        blocksize=NF4_BLOCK_SIZE,
        quant_type="nf4",
        compress_statistics=True,
    )
    return {
        "scheme": "nf4",
        "shape": list(weight.shape),
        "qweight": qweight.cpu().contiguous(),
        "quant_state": _tensor_to_cpu(quant_state.as_dict(packed=True)),
    }


def _dequantize_nf4(item: dict[str, Any], device: torch.device) -> torch.Tensor:
    qweight = item["qweight"].to(device)
    quant_state = {
        k: (v.to(device) if torch.is_tensor(v) else v)
        for k, v in item["quant_state"].items()
    }
    qs = bnbF.QuantState.from_dict(quant_state, device=device)
    weight = bnbF.dequantize_4bit(qweight, quant_state=qs)
    return weight.to(torch.float16)


def _quantize_fp16(weight: torch.Tensor) -> dict[str, Any]:
    return {
        "scheme": "fp16",
        "shape": list(weight.shape),
        "weight": weight.detach().to(torch.float16).cpu().contiguous(),
    }


def _dequantize_fp16(item: dict[str, Any], device: torch.device) -> torch.Tensor:
    return item["weight"].to(device=device, dtype=torch.float16)


def _pick_scheme(name: str, tensor: torch.Tensor) -> str:
    if tensor.ndim < 2:
        return "fp16"
    if any(token in name for token in INT8_TARGETS):
        return "int8_sym"
    return "nf4"


def _quantize_tensor(name: str, tensor: torch.Tensor) -> dict[str, Any]:
    scheme = _pick_scheme(name, tensor)
    if scheme == "fp16":
        return _quantize_fp16(tensor)
    if scheme == "int8_sym":
        return _quantize_int8(tensor)
    if scheme == "nf4":
        return _quantize_nf4(tensor)
    raise ValueError(f"Unknown scheme for {name}: {scheme}")


def _dequantize_tensor(item: dict[str, Any], device: torch.device) -> torch.Tensor:
    scheme = item["scheme"]
    if scheme == "fp16":
        return _dequantize_fp16(item, device)
    if scheme == "int8_sym":
        return _dequantize_int8(item, device)
    if scheme == "nf4":
        return _dequantize_nf4(item, device)
    raise ValueError(f"Unknown serialized scheme: {scheme}")


def _load_manifest() -> dict[str, Any]:
    return json.loads(MANIFEST_PATH.read_text())


def prepare_quantized_assets(force: bool = False) -> Path:
    if _artifacts_ready() and not force:
        return ARTIFACT_DIR

    ARTIFACT_DIR.mkdir(parents=True, exist_ok=True)
    device = "cuda:0" if torch.cuda.is_available() else "cpu"

    model = AutoModelForCausalLM.from_pretrained(
        MODEL_ID,
        torch_dtype=torch.float16,
        low_cpu_mem_usage=True,
        device_map=device,
    )
    model.eval()

    saved_files: list[str] = []
    embeddings_payload: dict[str, Any] = {}
    final_payload: dict[str, Any] = {}
    current_layer_idx: int | None = None
    current_layer_payload: dict[str, Any] = {}

    with torch.inference_mode():
        for name, param in model.named_parameters():
            if name == "lm_head.weight":
                # The checkpoint uses tied embeddings; we recreate that tie at load time.
                continue
            tensor = param.detach()
            payload = _quantize_tensor(name, tensor)
            if name.startswith("model.layers."):
                layer_idx = int(name.split(".")[2])
                if current_layer_idx is None:
                    current_layer_idx = layer_idx
                if layer_idx != current_layer_idx:
                    rel_path = f"layer_{current_layer_idx:02d}.pt"
                    torch.save(current_layer_payload, ARTIFACT_DIR / rel_path)
                    saved_files.append(rel_path)
                    current_layer_payload = {}
                    current_layer_idx = layer_idx
                current_layer_payload[name] = payload
            elif name.startswith("model.embed_tokens."):
                embeddings_payload[name] = payload
            else:
                final_payload[name] = payload
            del payload
            torch.cuda.empty_cache()

    if current_layer_idx is not None:
        rel_path = f"layer_{current_layer_idx:02d}.pt"
        torch.save(current_layer_payload, ARTIFACT_DIR / rel_path)
        saved_files.append(rel_path)

    torch.save(embeddings_payload, ARTIFACT_DIR / "embeddings.pt")
    saved_files.append("embeddings.pt")

    torch.save(final_payload, ARTIFACT_DIR / "final.pt")
    saved_files.append("final.pt")

    manifest = {
        "version": 1,
        "model_id": MODEL_ID,
        "int8_group_size": INT8_GROUP_SIZE,
        "nf4_block_size": NF4_BLOCK_SIZE,
        "files": saved_files,
    }
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2))

    del model
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()

    return ARTIFACT_DIR


def _build_empty_model() -> AutoModelForCausalLM:
    config = AutoConfig.from_pretrained(MODEL_ID)
    with init_empty_weights():
        model = AutoModelForCausalLM.from_config(config)
    return model


def load_model(device: str | torch.device = "cuda"):
    if not _artifacts_ready():
        prepare_quantized_assets()

    target_device = _resolve_device(device)
    model = _build_empty_model()
    manifest = _load_manifest()

    with torch.inference_mode():
        for rel_path in manifest["files"]:
            shard = torch.load(ARTIFACT_DIR / rel_path, map_location="cpu", weights_only=False)
            for name, item in shard.items():
                value = _dequantize_tensor(item, target_device)
                set_module_tensor_to_device(model, name, target_device, value=value)
                del value
            del shard
            gc.collect()
            if target_device.type == "cuda":
                torch.cuda.empty_cache()

    model.tie_weights()
    model.to(target_device)
    model.eval()
    return model


def get_compressed_size() -> int:
    if not _artifacts_ready():
        prepare_quantized_assets()
    total = 0
    for path in [MANIFEST_PATH, *_artifact_files()]:
        total += os.path.getsize(path)
    return int(total)


if __name__ == "__main__":
    prepare_quantized_assets()
    print(get_compressed_size())
